@charset "UTF-8";
/* Valores por defecto; JS los sobrescribe con appsmith.theme */
:root {
  --primary:#3b82f6;
  --bg:#ffffff;
  --radius:10px;
  --shadow:0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
  --border:#e5e7eb;
  --muted:#6b7280;
  --font: system-ui, -apple-system, Segoe UI, Roboto, Inter, sans-serif;
}

.card {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px;
  font-family: var(--font);
}

.toolbar {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 8px;
}

.search {
  position: relative;
  flex: 1;
  max-width: 260px;
}

.search input {
  width: 100%;
  padding: 8px 10px 8px 30px;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  outline: 0;
  font-family: var(--font);
  background: #fff;
}

.search .ico {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted);
}

table {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  font-family: var(--font);
}

thead th {
  background: #f8fafc;
  padding: 10px;
  text-align: left;
  font-weight: 600;
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}

tbody td {
  padding: 10px;
  border-bottom: 1px solid var(--border);
  font-size: 13px;
}

tbody tr:hover {
  background: #f5f9ff;
}

tbody tr.sel {
  background: #eaf2ff;
}

.btn-eye {
  background: var(--primary);
  color: #fff;
  border: none;
  padding: 6px 8px;
  border-radius: calc(var(--radius) - 4px);
  cursor: pointer;
}

.btn-eye:hover {
  filter: brightness(0.93);
}

/* Paginación en un solo bloque */
.pager {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
  margin-top: 8px;
  color: #111827;
  font-family: var(--font);
}

.pager .btn-nav {
  padding: 6px 12px;
  border: 1px solid var(--border);
  background: #fff;
  border-radius: calc(var(--radius) - 4px);
  cursor: pointer;
  font-family: var(--font);
}

.pager .btn-nav[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.pager .muted {
  color: var(--muted);
  font-size: 12px;
}

