import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import { createRoot } from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/client/+esm';
const h = React.createElement;

/* =========================
   THEME (Appsmith -> CSS vars en .cw-host)
   ========================= */
function readTheme() {
  const t = globalThis.appsmith && appsmith.theme ? appsmith.theme : {};
  const props = t.properties || {};
  const colors = props.colors || t.colors || {};
  const radius = (props.borderRadius || t.borderRadius || {}).appBorderRadius;
  const shadow = (props.boxShadow || t.boxShadow || {}).appBoxShadow;
  const font = (props.fontFamily || t.fontFamily || {}).appFont;
  return {
    primary: colors.primaryColor || '#3b82f6',
    bg: colors.backgroundColor || '#ffffff',
    radius: radius || '10px',
    shadow: shadow || '0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05)',
    font: font || 'Inter',
    border: '#e5e7eb',
    muted: '#6b7280'
  };
}
function applyThemeToHost(hostEl) {
  const t = readTheme();
  const st = hostEl.style;
  st.setProperty('--primary', t.primary);
  st.setProperty('--bg', t.bg);
  st.setProperty('--radius', t.radius);
  st.setProperty('--shadow', t.shadow);
  st.setProperty('--border', t.border);
  st.setProperty('--muted', t.muted);
  st.setProperty('--font', `'${t.font}', system-ui, -apple-system, Segoe UI, Roboto, Inter, sans-serif`);
}
function startThemeSync(hostEl) {
  let last = JSON.stringify(readTheme());
  applyThemeToHost(hostEl);
  const id = setInterval(() => {
    const now = JSON.stringify(readTheme());
    if (now !== last) {
      last = now;
      applyThemeToHost(hostEl);
    }
  }, 1000);
  return () => clearInterval(id);
}

/* =========================
   Eventos hacia fuera
   ========================= */
function verDetalle(reg) {
  appsmith.updateModel({
    selected: reg
  });
  appsmith.triggerEvent('verDetalle', reg);
}

/* =========================
   MODEL (reacciona a cambios del Default Model)
   ========================= */
function readRows(m) {
  const model = m ?? appsmith?.model;
  if (!model) return [];
  if (Array.isArray(model)) return model; // modelo = array
  if (Array.isArray(model.rows)) return model.rows; // { rows: [...] }
  if (Array.isArray(model.items)) return model.items; // REST común
  if (Array.isArray(model.data)) return model.data; // REST común
  return [];
}
function useModelRows() {
  const [rows, setRows] = React.useState(readRows());
  React.useEffect(() => {
    const apply = mm => setRows(readRows(mm));

    // primera carga
    apply();

    // suscripción reactiva
    if (typeof appsmith?.onModelChange === 'function') {
      appsmith.onModelChange(apply);
      return () => {};
    }

    // fallback (por si onModelChange no existe)
    const id = setInterval(() => apply(), 500);
    return () => clearInterval(id);
  }, []);
  return rows;
}

/* =========================
   Icono Search
   ========================= */
const IcoSearch = () => h('svg', {
  width: 16,
  height: 16,
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 2
}, h('circle', {
  cx: 11,
  cy: 11,
  r: 7
}), h('line', {
  x1: 21,
  y1: 21,
  x2: 16.65,
  y2: 16.65
}));

/* =========================
   APP
   ========================= */
function App() {
  // Datos del Default Model (reactivo)
  const rows = useModelRows();

  // Estado UI
  const [q, setQ] = React.useState('');
  const [pageSize, setPageSize] = React.useState(5);
  const [page, setPage] = React.useState(1);
  const [selected, setSelected] = React.useState(null);

  // 🔎 Campos exactos a buscar
  const keys = ['user_identification', 'user_login', 'user_first_name', 'user_last_name', 'user_t24'];
  const norm = s => String(s ?? '').toLowerCase();

  // Búsqueda client-side
  const filtradas = React.useMemo(() => {
    const t = norm(q.trim());
    if (!t) return rows;
    return rows.filter(r => keys.some(k => norm(r?.[k]).includes(t)));
  }, [q, rows]);

  // Paginación (client-side)
  const total = filtradas.length;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  React.useEffect(() => {
    if (page > totalPages) setPage(1);
  }, [totalPages]);
  React.useEffect(() => {
    setPage(1);
  }, [q]);
  const from = (page - 1) * pageSize,
    to = from + pageSize;
  const pageData = filtradas.slice(from, to);
  const start = total === 0 ? 0 : from + 1,
    end = total === 0 ? 0 : Math.min(to, total);

  // helper id coherente por fila
  const rowId = (r, i) => r?.id ?? r?.user_identification ?? i;
  return h('div', {
    className: 'card'
  },
  // Toolbar
  h('div', {
    className: 'toolbar'
  }, h('div', {
    className: 'search'
  }, h('span', {
    className: 'ico'
  }, h(IcoSearch)), h('input', {
    placeholder: 'Search…',
    value: q,
    onChange: e => setQ(e.target.value)
  }))),
  // Tabla
  h('table', null, h('thead', null, h('tr', null, h('th', null, 'Documento'), h('th', null, 'Usuario'), h('th', null, 'Nombres'), h('th', null, 'Apellidos'), h('th', null, 'IdCliente'), h('th', null, 'Detalle'))), h('tbody', null, pageData.length ? pageData.map((r, i) => h('tr', {
    key: rowId(r, i),
    className: selected === rowId(r, i) ? 'sel' : '',
    onClick: () => setSelected(rowId(r, i))
  }, h('td', null, r?.user_identification ?? ''), h('td', null, r?.user_login ?? ''), h('td', null, r?.user_first_name ?? ''), h('td', null, r?.user_last_name ?? ''), h('td', null, r?.user_t24 ?? ''), h('td', null, h('button', {
    className: 'btn-eye',
    onClick: () => verDetalle(r),
    title: 'Ver detalle',
    'aria-label': 'Ver detalle'
  }, '👁️')))) : h('tr', null, h('td', {
    colSpan: 6
  }, h('div', {
    style: {
      textAlign: 'center',
      padding: '18px',
      color: 'var(--muted)'
    }
  }, 'Sin datos'))))),
  // Paginación
  h('div', {
    className: 'pager'
  }, h('span', {
    className: 'muted'
  }, `${start}-${end} de ${total} · Página ${page} de ${totalPages}`), h('button', {
    className: 'btn-nav',
    onClick: () => setPage(1),
    disabled: page <= 1
  }, 'Primera'), h('button', {
    className: 'btn-nav',
    onClick: () => setPage(p => Math.max(1, p - 1)),
    disabled: page <= 1
  }, 'Anterior'), h('select', {
    value: pageSize,
    onChange: e => {
      setPageSize(Number(e.target.value));
      setPage(1);
    }
  }, [5, 10, 20, 50].map(n => h('option', {
    key: n,
    value: n
  }, `${n}/pág`))), h('button', {
    className: 'btn-nav',
    onClick: () => setPage(p => Math.min(totalPages, p + 1)),
    disabled: page >= totalPages
  }, 'Siguiente'), h('button', {
    className: 'btn-nav',
    onClick: () => setPage(totalPages),
    disabled: page >= totalPages
  }, 'Última')));
}

/* =========================
   MOUNT
   ========================= */
function mount() {
  const host = document.querySelector('.cw-host') || document.documentElement;
  startThemeSync(host); // aplica y mantiene el tema de Appsmith
  const el = document.getElementById('root');
  if (el) createRoot(el).render(h(App));
}
