		if(appsmith.store.optionSelected==undefined) {			
			storeValue("optionSelected","",true)			
		}

		if(!appsmith.store.paramTexto) {			
			storeValue("paramTexto","",true)			
		}else{
			paramTexto.setValue(appsmith.store.paramTexto);
		}

		if(!appsmith.store.paramNumber) {			
			storeValue("paramNumber","",true)			
		}else{
			paramNumber.setValue(appsmith.store.paramNumber);
		}


	},

}

export default {
  async afterUpdate() {
    try {
      const id = appsmith.store.usuarioData.id;
      await userXid.run({ id });                         // 1) reconsultar
      const row = Array.isArray(userXid.data) ? (userXid.data[0] || {}) : (userXid.data || {});
      await storeValue('usuarioData', row);              // 2) guardar en store
      closeModal('confirmarEstado');                     // 3) cerrar modal
      resetWidget('chkLocked', true);                    // 4) re-sincronizar checkbox (si aplica)
      showAlert('Estado actualizado', 'success');        // 5) feedback
      // (Opcional) Notificar a un custom widget:
      // appsmith.triggerEvent('usuarioActualizado', row);
    } catch (e) {
      showAlert('No se pudo refrescar el usuario', 'error');
      console.error(e);
    }
  }
}

